SELECT MONTH(s.opened_date) AS opened_month, CASE WHEN s.sqft >= 14622 THEN 'high' WHEN s.sqft >= 6866 THEN 'mid' ELSE 'low' END AS sqft_bucket, MAX(ss.revenue) AS max_revenue FROM store_sales ss LEFT JOIN products p ON p.id = ss.product_id RIGHT JOIN stores s ON s.id = ss.store_id GROUP BY MONTH(s.opened_date), CASE WHEN s.sqft >= 14622 THEN 'high' WHEN s.sqft >= 6866 THEN 'mid' ELSE 'low' END ORDER BY max_revenue
